"""Edge-case tests for phase-11-interactive — generated by bug-hunter agent (round 2).

Round 2 focus: configure() effects on interactive output, structural features
in interactive mode, format presets in interactive tooltips, annotation
rendering in interactive scenes (re-verify round 1 findings), configure+interactive
combined edge cases, composition corners, degenerate data through packed binary
path, type boundaries at the PyO3/Arrow CDI interface.
"""

from __future__ import annotations

import json
import tempfile

import polars as pl
import pytest

import ferrum as fr
from ferrum._interactive import (
    InteractiveChart,
    _render_scene,
)


def _simple_chart(n: int = 3) -> "fr.chart.Chart":
    df = pl.DataFrame({"x": list(range(n, n + 3)), "y": list(range(n, n + 3))})
    return fr.Chart(df).mark_point().encode(x="x", y="y")


def _scene(chart):
    """Return parsed scene dict from the interactive pipeline."""
    scene_json, packed = _render_scene(chart)
    return json.loads(scene_json), packed


