def test_configure_axis_label_font_size_affects_interactive_scene():
    """configure_axis(label_font_size=) must change text element font_size in scene."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    chart_small = (
        fr.Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .configure_axis(label_font_size=8)
    )
    chart_large = (
        fr.Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .configure_axis(label_font_size=24)
    )
    scene_small, _ = _scene(chart_small)
    scene_large, _ = _scene(chart_large)
    # Both must produce valid scenes with panels
    assert len(scene_small["panels"]) >= 1
    assert len(scene_large["panels"]) >= 1
    # The scene JSON text for large font must differ from small font
    # (at minimum the font_size values in axis text nodes differ)
    json_small = json.dumps(scene_small)
    json_large = json.dumps(scene_large)
    assert json_small != json_large, (
        "configure_axis(label_font_size) must produce different interactive scenes"
    )


def test_configure_title_font_size_in_interactive_scene():
    """configure_title(font_size=) must flow through to interactive scene title nodes."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    chart = (
        fr.Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .properties(title="Test Title")
        .configure_title(font_size=28)
    )
    scene, _ = _scene(chart)
    title_nodes = scene.get("title", [])
    assert len(title_nodes) > 0, "title nodes must be present"
    # At least one title text node must have font_size >= 28
    has_large_font = False
    for node in title_nodes:
        if "style" in node and node["style"].get("font_size", 0) >= 28:
            has_large_font = True
            break
    assert has_large_font, (
        f"configure_title(font_size=28) must produce a title node with font_size >= 28; "
        f"got {title_nodes}"
    )


def test_configure_padding_changes_plot_area():
    """configure_padding must change plot_area dimensions in interactive scene."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    chart_default = fr.Chart(df).mark_point().encode(x="x", y="y")
    chart_padded = (
        fr.Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .configure_padding(left=100, right=50, top=60, bottom=80)
    )
    scene_default, _ = _scene(chart_default)
    scene_padded, _ = _scene(chart_padded)
    pa_default = scene_default["panels"][0]["plot_area"]
    pa_padded = scene_padded["panels"][0]["plot_area"]
    # Heavy padding should shrink the plot area or shift its position
    assert pa_default != pa_padded, (
        "configure_padding must change plot_area dimensions in interactive scene"
    )


