# ============================================================================
# Composition corners with interactive
# ============================================================================


def test_hconcat_three_charts_interactive():
    """HConcat with 3 charts must produce valid interactive scene."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    c1 = fr.Chart(df).mark_point().encode(x="x", y="y")
    c2 = fr.Chart(df).mark_bar().encode(x="x", y="y")
    c3 = fr.Chart(df).mark_line().encode(x="x", y="y")
    concat = c1 | c2 | c3
    scene_json, _ = concat._render_interactive()
    scene = json.loads(scene_json)
    assert "panels" in scene
    assert "NaN" not in scene_json


def test_vconcat_with_different_data_interactive():
    """VConcat with different datasets must not crash."""
    df1 = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    df2 = pl.DataFrame({"a": ["x", "y", "z"], "b": [10.0, 20.0, 30.0]})
    c1 = fr.Chart(df1).mark_point().encode(x="x", y="y")
    c2 = fr.Chart(df2).mark_bar().encode(x="a", y="b")
    concat = c1 & c2
    scene_json, _ = concat._render_interactive()
    scene = json.loads(scene_json)
    assert "panels" in scene


def test_hconcat_with_empty_and_nonempty_interactive():
    """HConcat with one empty-data chart and one non-empty must not crash."""
    df_empty = pl.DataFrame({
        "x": pl.Series([], dtype=pl.Float64),
        "y": pl.Series([], dtype=pl.Float64),
    })
    df_normal = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    c1 = fr.Chart(df_empty).mark_point().encode(x="x", y="y")
    c2 = fr.Chart(df_normal).mark_point().encode(x="x", y="y")
    concat = c1 | c2
    scene_json, _ = concat._render_interactive()
    scene = json.loads(scene_json)
    assert "panels" in scene


def test_layer_merge_with_different_marks_interactive():
    """Layer merge (point + line + bar) must render interactively."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    layered = (
        fr.Chart(df).mark_point().encode(x="x", y="y")
        + fr.Chart(df).mark_line().encode(x="x", y="y")
    )
    scene_json, _ = _render_scene(layered)
    scene = json.loads(scene_json)
    assert len(scene["panels"]) >= 1
    # Must have at least 2 mark batches (point + line)
    assert len(scene["panels"][0]["marks"]) >= 2


