def test_scene_no_nan_or_infinity_in_mark_nodes():
    """Mark node coordinates must not contain NaN or Infinity strings."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y")
