def test_interactive_save_produces_valid_html_with_no_nan():
    """InteractiveChart.save() must produce valid HTML with no NaN in scene."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    ic = InteractiveChart(fr.Chart(df).mark_point().encode(x="x", y="y"))
    with tempfile.NamedTemporaryFile(suffix=".html", delete=False) as f:
        ic.save(f.name)
        html = open(f.name).read()
    assert "<html" in html.lower() or "<!doctype" in html.lower()
    assert "NaN" not in ic.scene_json


def test_interactive_save_with_title():
    """InteractiveChart.save() with a chart title must not crash."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y").properties(title="My Plot")
    ic = InteractiveChart(chart)
    with tempfile.NamedTemporaryFile(suffix=".html", delete=False) as f:
        ic.save(f.name)
        html = open(f.name).read()
    assert "My Plot" in html or len(html) > 100


def test_interactive_save_with_embed_wasm_false():
    """InteractiveChart.save() with embed_wasm=False must not crash."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
