def test_interaction_config_has_expected_keys():
    """Scene interaction config must have zoom/pan/toolbar keys."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y")
    scene, _ = _scene(chart)
    interaction = scene.get("interaction", {})
    assert isinstance(interaction, dict)
    # Must have at least zoom_enabled and pan_enabled
    assert "zoom_enabled" in interaction or "conditionals" in interaction, (
        f"interaction config must have expected keys; got {list(interaction.keys())}"
    )


def test_conditionals_list_empty_without_selections():
    """Without selections, conditionals list must be empty."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [2.0, 4.0, 6.0]})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y")
    scene, _ = _scene(chart)
    conditionals = scene.get("interaction", {}).get("conditionals", [])
    assert len(conditionals) == 0, "no selections = no conditionals"


