# ============================================================================
# _apply_zoom_domains edge cases
# ============================================================================


def test_apply_zoom_domains_negative_domain():
    """Zoom with negative domain values must not crash."""
    chart = _simple_chart()
    ic = InteractiveChart(chart)
    result = ic._apply_zoom_domains({"0": {"x_domain": [-10.0, -1.0], "y_domain": [-5.0, -0.5]}})
    scene_json, _ = _render_scene(result)
    assert "NaN" not in scene_json


def test_apply_zoom_domains_reversed_domain():
    """Zoom with reversed domain (max < min) must not crash."""
    chart = _simple_chart()
    ic = InteractiveChart(chart)
    # Some zoom gestures can produce reversed domains temporarily
    result = ic._apply_zoom_domains({"0": {"x_domain": [10.0, 0.0]}})
    assert result is not None


def test_apply_zoom_domains_very_small_domain():
    """Zoom to very small domain range must not crash."""
    chart = _simple_chart()
    ic = InteractiveChart(chart)
    result = ic._apply_zoom_domains({"0": {"x_domain": [1.999999, 2.000001]}})
    assert result is not None


