def test_repr_mimebundle_returns_dict_or_none():
    """_repr_mimebundle_ must return a dict (with anywidget) or None (without)."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    ic = InteractiveChart(fr.Chart(df).mark_point().encode(x="x", y="y"))
    result = ic._repr_mimebundle_()
    assert result is None or isinstance(result, (dict, tuple))


def test_interactive_repr_string():
    """__repr__ must include InteractiveChart and selections count."""
    chart = _simple_chart()
    ic = InteractiveChart(chart)
    r = repr(ic)
    assert "InteractiveChart" in r
    assert "selections=" in r
